        var sut = CreateSut(boardRepo: boardRepo);

        var act = () => sut.CreateAsync(Guid.NewGuid(), new CreateLaneRequest("Lane"));

        await act.Should().ThrowAsync<NotFoundException>()
            .Where(e => e.Code == "board.not_found");
