    [Fact]
    public async Task DeleteAsync_ExistingLane_DeletesAndShiftsPositions()
    {
        var laneId = Guid.NewGuid();
        var lane = ALane().WithId(laneId).OnBoard(_boardId).AtPosition(2).Build();
